		public PrivacyNoticeTest setHandler(Handler handler) {
			this.handler = handler;
			LOGGER.addHandler(handler); // assign so the LOGGER can only output results to the Handler
			return this;
		}

		/**
		 * Returns a new populated PrivacyNotice
		 * 
		 * @return PrivacyNotice
		 */
		protected PrivacyNotice generateNewEntity() {
			PrivacyNotice entity = new PrivacyNotice( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),   new Date(),  new URL(),  new HashSet<>(),  null,  new HashSet<>(),  DocumentStatus.values()[0] );
			
			return( entity );
		}

